// ---------- المنقذ: بوت مساعد بمفاهيم المنهج (مبني على معرفة شاملة لكل الفصل الأول، مجاني بالكامل، بدون أي API) ----------
const KNOWLEDGE_BASE = [
  // ===== الوحدة 1: الأرض من حولي =====
  {k:["الفرق بين الطقس والمناخ","طقس","مناخ"], a:"الطقس هو حالة الجو المتغيرة يومياً، بينما المناخ هو حالة الجو السائدة في مكان ما على مدى فترة طويلة من الزمن.", unit:1},
  {k:["عناصر المناخ"], a:"عناصر المناخ أربعة: الحرارة، الضغط الجوي، الرياح، والرطوبة والتكاثف.", unit:1},
  {k:["اشعاع شمسي","إشعاع شمسي","مصدر الحرارة"], a:"الإشعاع الشمسي هو مقدار الأشعة الشمسية الساقطة على مساحة معينة، وهو مصدر الحرارة الرئيس للكرة الأرضية.", unit:1},
  {k:["مناطق حرارية","المنطقة الحارة","المنطقة الباردة القطبية","المنطقة المعتدلة","اكبر منطقة حرارية","اكبر المناطق الحرارية امتدادا"], a:"سطح الأرض مقسّم لـ4 مناطق حرارية: الحارة (0-30°، الأكبر امتداداً)، المعتدلة الدافئة (30-40°)، المعتدلة الباردة (40-66.5°)، والباردة القطبية (66.5-90°).", unit:1},
  {k:["ضغط جوي","الضغط","الضغط المرتفع","الضغط المنخفض","العلاقة بين الحرارة والضغط","علاقة الضغط بالحرارة","حرف H","حرف L"], a:"الضغط الجوي هو وزن عمود من الهواء على مساحة ما من سطح الأرض. له علاقة عكسية مع الحرارة والارتفاع — كل ما ارتفعنا، قلّ الضغط. يُرمز للمرتفع بحرف H وللمنخفض بحرف L.", unit:1},
  {k:["انواع الرياح","أنواع الرياح"], a:"الرياح 4 أنواع: الدائمة (تهب بانتظام طوال العام)، الموسمية (تتغير باختلاف الفصل)، المحلية (زي الكوس بقطر)، واليومية (نسيم البر والبحر).", unit:1},
  {k:["تعريف الرياح","ما هي الرياح","حركة الهواء","حركة الرياح","كيف تتحرك الرياح"], a:"الرياح هي حركة الهواء الأفقية من منطقة الضغط المرتفع إلى منطقة الضغط المنخفض، وتُصنَّف إلى أربعة أنواع رئيسة: الدائمة، والموسمية، والمحلية، واليومية.", unit:1},
  {k:["الرياح في القران","ذكر الرياح في القران"], a:"ورد ذكر الرياح في القرآن الكريم في مواضع عدة، منها سورة الروم وسورة الذاريات — فالرياح قد تكون رحمة، وقد تكون عذاباً بأمر الله تعالى.", unit:1},
  {k:["الحرارة","اهمية الحرارة","طول النهار","اختلاف الحرارة","تختلف الحرارة من مكان لمكان"], a:"تُعدّ الحرارة من أهم عناصر المناخ؛ لتأثيرها المباشر على الإنسان وأنشطته المختلفة، وتؤثر في جميع عناصر المناخ الأخرى. مصدرها الرئيس الإشعاع الشمسي، وتختلف من منطقة لأخرى باختلاف زاوية سقوط أشعة الشمس وطول النهار.", unit:1},
  {k:["رياح دائمة"], a:"الرياح الدائمة تهب بانتظام طوال العام من مناطق الضغط المرتفع إلى مناطق الضغط المنخفض.", unit:1},
  {k:["دوائر العرض","الموقع بالنسبة لدوائر العرض","خطوط العرض والحرارة"], a:"الموقع بالنسبة لدوائر العرض يؤثر في زاوية سقوط أشعة الشمس، وبالتالي في كمية الحرارة المكتسبة.", extra:"كل ما اقتربت من خط الاستواء صارت الأشعة عمودية أكثر، والحرارة أعلى.", unit:1},
  {k:["دجلة والفرات","نهرا دجلة والفرات","انهار الرافدين"], a:"نهرا دجلة والفرات وفّرا لبلاد الرافدين التربة الخصبة والمياه العذبة ووسائل النقل.", extra:"اسم «بلاد الرافدين» جاء من هذين النهرين — الرافد يعني النهر.", unit:2},
  {k:["الهجرات البشرية","هجرات","استقرار في الرافدين"], a:"هاجرت جماعات من شبه الجزيرة العربية واستقرت في بلاد الرافدين، وهذا أحد عوامل قيام حضاراتها.", unit:2},
  {k:["الموقع الجغرافي للرافدين","موقع بلاد الرافدين"], a:"وقوع بلاد الرافدين وسط صحارٍ شكّل حافزاً قوياً للاستقرار حول مصادر المياه.", unit:2},
  {k:["الزراعة في الرافدين","الزراعة في بلاد الرافدين","زراعة"], a:"زرع أهل بلاد الرافدين القمح والشعير والفواكه والتمور، ومن أبرز إنجازاتهم الزراعية حدائق بابل المعلقة.", unit:2},
  {k:["الصناعة في الرافدين","الصناعة في بلاد الرافدين","صناعة","صنعوا"], a:"صنع أهل بلاد الرافدين الأسلحة والحلي وأدوات الزراعة والفخار.", unit:2},
  {k:["العمارة في الرافدين","العمارة في بلاد الرافدين","عمارة"], a:"من عمارة بلاد الرافدين برج بابل، وبوابة عشتار التي بناها نبوخذ نصر عام 575 ق.م، وهي مزخرفة برسوم حيوانات وموجودة حالياً في متحف برلين.", unit:2},
  {k:["النحت في الرافدين","النحت في بلاد الرافدين","نحت","الحياة الفنية في الرافدين"], a:"من نحت بلاد الرافدين الثور المجنح الذي نحته الملك الآشوري سرجون الثاني ليرمز للقوة والحكمة، والمسلات التي نُقشت عليها أهم الأحداث الحربية.", unit:2},
  {k:["نبوخذ نصر"], a:"نبوخذ نصر ملك بابلي، بنى بوابة عشتار عام 575 ق.م.", unit:2},
  {k:["التضاريس وتوزيع السكان","اثر التضاريس"], a:"التضاريس من العوامل الطبيعية المؤثرة في توزيع السكان: السهول جاذبة لسهولة الحركة وخصوبة التربة، والجبال طاردة لوعورتها.", unit:4},
  {k:["سقوط بغداد","سقطت بغداد","نهاية الدولة العباسية","سقوط الخلافة العباسية"], a:"سقطت بغداد سنة 656هـ على يد المغول، وبها انتهت الدولة العباسية (132–656هـ).", extra:"قبل السقوط مرّت الدولة بعصر ضعف (العصر العباسي الثاني): تفككت إلى دويلات مستقلة، وانتشر الفساد والانغماس في الترف، وتنامى خطر المغول من الشرق والصليبيين من الغرب.", unit:5},
  {k:["معركة الزاب","ثورة العباسيين","خراسان","ضعف الدولة الاموية"], a:"ضعفت الدولة الأموية في أواخر عهدها نتيجة الفساد الإداري والاقتصادي، فقام العباسيون بثورة انطلقت من إقليم خراسان، وانتصروا على الجيش الأموي في معركة الزاب الكبير في العراق.", unit:5},
  {k:["الكثافة السكانية","كثافه سكانيه"], a:"الكثافة السكانية تتأثر بالمناخ: تقل في المناطق شديدة الحرارة والجفاف (كالصحاري العربية والإفريقية) وشديدة البرودة (كسيبيريا)، وترتبط غالباً بخريطة الأمطار — مع استثناء حوضي الكونغو والأمازون رغم غزارة أمطارهما.", unit:4},
  {k:["رياح موسمية","رياح موسمية صيفية","رياح موسمية شتوية"], a:"الرياح الموسمية تهب بمواسم معينة بسبب اختلاف الحرارة والضغط بين اليابس والماء. الصيفية تهب من الماء لليابس (ممطرة)، والشتوية من اليابس للماء (جافة غالباً).", unit:1},
  {k:["رياح محلية","رياح الطوز","الطوز","المسترال","رياح حارة","رياح باردة"], a:"الرياح المحلية تهب على مناطق محدودة ولفترات زمنية قصيرة، وتنقسم إلى رياح حارة (مثل الكوس في دولة قطر، والطوز في الكويت) ورياح باردة (مثل المسترال في فرنسا).", unit:1},
  {k:["كوس"], a:"الكوس رياح محلية حارة رطبة تهب على دولة قطر بفصلي الربيع والصيف، محمّلة بالأتربة والغبار، وتسبب تعذر الرؤية.", unit:1},
  {k:["رياح يومية","نسيم البر والبحر","نسيم الجبل والوادي"], a:"الرياح اليومية تهب يومياً بسبب اختلاف الحرارة ليلاً ونهاراً، نوعان: نسيم البر والبحر، ونسيم الجبل والوادي.", unit:1},
  {k:["رطوبة","تكاثف","مظاهر التكاثف","الضباب","الندى","بخار الماء"], a:"الرطوبة هي بخار الماء بالهواء، والتكاثف يحدث لما يتحول بخار الماء لحالة سائلة أو صلبة. من مظاهره: الضباب، الندى، السحب، والتساقط.", unit:1},
  {k:["عوامل مؤثرة في المناخ","عوامل المناخ"], a:"3 عوامل تؤثر بالمناخ: الموقع بالنسبة لدوائر العرض، الارتفاع عن سطح البحر، وتوزيع اليابس والماء.", unit:1},
  {k:["ارتفاع عن سطح البحر","150 متر","الثلوج على قمم الجبال","الجبال باردة","برودة الجبال"], a:"تنخفض درجة الحرارة درجة مئوية واحدة كل 150 متر ارتفاع عن سطح البحر، ويقل الضغط الجوي أيضاً كلما ارتفعنا. لهذا تغطي الثلوج قمم الجبال.", unit:1},
  {k:["ظل المطر","السفوح المواجهة للرياح"], a:"تسقط الأمطار بغزارة على سفوح الجبال المواجهة للرياح، بينما تقل على السفوح الخلفية وتسمى مناطق ظل المطر.", unit:1},
  {k:["توزيع اليابس والماء","المناطق الساحلية","المناطق الداخلية","الساحل","المناطق الساحلية معتدلة","اعتدال حرارة السواحل"], a:"المناطق الساحلية تتميز باعتدال حرارتها معظم السنة، بينما المناطق الداخلية شديدة الحرارة صيفاً وشديدة البرودة شتاءً.", unit:1},
  {k:["اقليم مناخي","إقليم مناخي"], a:"الإقليم المناخي هو منطقة متشابهة بخصائصها المناخية (حرارة، أمطار، رياح، رطوبة) ومتميزة عن الأقاليم المجاورة.", extra:"تشبيه يقرّبها: تخيل خريطة العالم مقسّمة لأحياء، كل حي له 'طابعه الجوي' الخاص — بيت بالإقليم الاستوائي عايش حر ومطر طول السنة، بينما بيت بالإقليم القطبي عايش برد قارس أغلب الوقت، رغم إنهم بنفس الكوكب.", unit:1},
  {k:["اقاليم مناخية","أقاليم العالم"], a:"8 أقاليم مناخية رئيسة: الاستوائي، المداري، الصحراوي (قطر ضمنه)، البحر المتوسط، الصيني، غرب أوروبا، اللورانسي، والقطبي البارد.", unit:1},
  {k:["اقليم صحراوي","الإقليم الصحراوي","اقليم قطر المناخي","اقليم قطر","مناخ قطر"], a:"الإقليم الصحراوي يمتد بين دائرتي عرض 18° و30°، ودولة قطر تقع ضمن هذا الإقليم: صيف حار جاف طويل، وشتاء بارد نسبياً قليل الأمطار أو نادرها.", unit:1},
  {k:["اقليم استوائي","الإقليم الاستوائي"], a:"الإقليم الاستوائي يمتد بين دائرتي عرض 0° و8°، حار ممطر طوال العام.", unit:1},
  {k:["اقليم مداري","الإقليم المداري","السافانا","الاسود والفيلة"], a:"الإقليم المداري بين 8° و18°: صيف طويل حار ممطر، وشتاء قصير دافئ جاف. تعيش فيه حيوانات مثل الأسود والنمور والفيلة والحُمُر الوحشية، وتنمو فيه الحشائش الطويلة (السافانا).", unit:1},
  {k:["اقليم البحر المتوسط","البحر المتوسط"], a:"إقليم البحر المتوسط بين 30° و40° غرب القارات، صيف حار جاف وشتاء دافئ ممطر.", unit:1},
  {k:["اقليم صيني","الإقليم الصيني","الصيني"], a:"الإقليم الصيني بين 30° و40° شرق القارات، صيف حار وشتاء دافئ، وأمطار طوال العام.", unit:1},
  {k:["اقليم غرب اوروبا","إقليم غرب أوروبا","غرب اوروبا"], a:"إقليم غرب أوروبا بين دائرتي عرض 40° و60° غرب القارات: شتاء بارد وصيف معتدل، وتزداد الأمطار في فصل الصيف.", unit:1},
  {k:["الاقليم اللورانسي","اللورانسي"], a:"الإقليم اللورانسي بين دائرتي عرض 40° و60° شرق القارات: شتاء بارد وصيف معتدل، لكن الأمطار تزداد في فصل الشتاء.", extra:"يشبه إقليم غرب أوروبا في الحرارة، والفرق في موسم المطر: غرب أوروبا تزداد أمطاره صيفاً، واللورانسي تزداد أمطاره شتاءً.", unit:1},
  {k:["اقليم قطبي","القطبي البارد","تساقط الثلوج"], a:"الإقليم القطبي البارد بين 60° و90°: شتاء طويل شديد البرودة، وصيف قصير معتدل البرودة، ويكون التساقط على هيئة ثلوج.", unit:1},

  // ===== الوحدة 2: حضارة بلاد الرافدين =====
  {k:["حضارة","تعريف الحضارة"], a:"الحضارة هي كل ما أنتجه العقل الإنساني من مظاهر مادية (مباني، أدوات) أو معنوية (ثقافة، عادات، فنون).", extra:"مثال معاصر يقرّب الفكرة: التقنية اللي نستخدمها اليوم (الجوالات، الإنترنت) هي حضارة عصرنا، تماماً زي ما كانت الكتابة المسمارية حضارة عصر بلاد الرافدين — كل جيل يضيف مظاهر مادية ومعنوية جديدة.", unit:2},
  {k:["بلاد الرافدين"], a:"بلاد الرافدين هي المنطقة الواقعة بين نهري دجلة والفرات، في جمهورية العراق حالياً.", unit:2},
  {k:["عوامل قيام حضارة الرافدين"], a:"3 عوامل: الموقع الجغرافي (وسط صحاري)، نهرا دجلة والفرات (خصوبة وماء)، والهجرات البشرية من الجزيرة العربية.", unit:2},
  {k:["سومريون","سومريين","اول الشعوب التي سكنت بلاد الرافدين","اول من سكن بلاد الرافدين","عاصمة السومريين","اورنمو"], a:"السومريون أول الشعوب التي سكنت بلاد الرافدين (نحو 4000 ق.م)، اتخذوا مدينة أور عاصمة لهم، ومن أشهر ملوكهم أورنمو. سقطت دولتهم على يد الأكاديين.", unit:2},
  {k:["اكاديون","الأكاديون","اكاديين","سرجون","سرجون الاول"], extra:"قصة من التاريخ: يُروى أن سرجون الأول وُلد لأسرة فقيرة، وتُرك طفلاً بالقرب من النهر، فوجده أحدهم وربّاه في القصر، وترقّى حتى أصبح ضابطاً عسكرياً ثم قائداً وفاتحاً عظيماً — قصة تحمل دروساً في الإصرار وتجاوز الصعاب.", a:"الأكاديون هاجروا من الجزيرة العربية (2350 ق.م)، قائدهم سرجون الأول أنهى حكم السومريين واتخذ من أكاد عاصمة له. سقطت دولتهم عام 2159 ق.م.", unit:2},
  {k:["قصة سرجون","قصة سرجون الاول","طفولة سرجون"], a:"يُروى أن سرجون الأول وُلد لأسرة فقيرة، وتُرك طفلاً بالقرب من النهر، فوجده أحدهم وربّاه في القصر، وترقّى حتى أصبح ضابطاً عسكرياً ثم قائداً وفاتحاً عظيماً — قصة تحمل دروساً في الإصرار وتجاوز الصعاب.", unit:2},
  {k:["بابليون","بابليين","الدولة البابلية الأولى","عاصمة البابليين"], a:"البابليون (الدولة البابلية الأولى، نحو 1880 ق.م) هاجروا من شبه الجزيرة العربية واتخذوا من بابل عاصمة، وأشهر ملوكهم حمورابي. سقطت دولتهم عام 1531 ق.م بسبب ضعف الملوك من بعده وكثرة الثورات الداخلية.", unit:2},
  {k:["حمورابي","قانون حمورابي","ملوك بابل","اشهر ملوك بابل","ملك بابل","اشهر ملوك الدولة البابلية"], a:"حمورابي أشهر ملوك الدولة البابلية الأولى، اشتهر بتشريعاته وقوانينه اللي نُقشت على مسلة حجرية باللغة البابلية — من أقدم القوانين المكتشفة بالعالم، ومبدؤها حماية الضعيف من القوي.", extra:"هدف قانونه تحقيق العدالة بين أفراد المجتمع، بما في ذلك الأيتام والأرامل. وحمورابي هو الملك الذي ثبّت دعائم دولته بالتشريعات والقوانين.", unit:2},
  {k:["اشوريون","آشوريون","اشوريين","اشور بانيبال"], a:"الآشوريون هاجروا من الجزيرة العربية واستقروا شمال بلاد الرافدين (1100 ق.م)، أشهر ملوكهم آشور بانيبال، سقطت دولتهم نهاية القرن السابع ق.م على يد الكلدانيين.", unit:2},
  {k:["كلدانيون","كلدانيين","الدولة البابلية الثانية","قورش","الفرس","فتح العراق","فتح المسلمين بلاد الرافدين","فتح المسلمون العراق"], a:"الكلدانيون أسسوا الدولة البابلية الثانية (627 ق.م)، وأشهر ملوكهم نبوخذ نصر. سقطت دولتهم عام 538 ق.م على يد الفرس بقيادة قورش، وبقيت المنطقة جزءاً من الإمبراطورية الفارسية أكثر من 13 قرناً، حتى فتحها المسلمون سنة 636م.", unit:2},
  {k:["نظام الحكم في الرافدين","نظام الحكم في بلاد الرافدين","الحياة السياسية في الرافدين","الملك في بلاد الرافدين","الملك في الرافدين"], a:"كان نظام الحكم في بلاد الرافدين ملكياً وراثياً، الملك هو القائد الأعلى للجيش، يساعده وزير وحكام على رأس الأقاليم.", unit:2},
  {k:["طبقات المجتمع في الرافدين","طبقات المجتمع في بلاد الرافدين","الحياة الاجتماعية في الرافدين","الطبقة الوسطى","الكهنة","الطبقة العليا","الطبقة الدنيا"], a:"تألّف المجتمع في بلاد الرافدين من ثلاث طبقات: الطبقة العليا (رجال الدولة والكهنة ومُلّاك الأراضي وكبار التجار)، ثم الطبقة الوسطى (العمّال والفلاحون)، ثم الطبقة الدنيا (أسرى الحروب والعبيد).", unit:2},
  {k:["الحياة الدينية في الرافدين","الحياة الدينية في بلاد الرافدين","عقيدة سكان الرافدين","ديانة الرافدين","تعدد المعبودات","الحياة بعد الموت","بعد الموت"], a:"تميزت بتعدد المعبودات (لكل مدينة إله)، والإيمان بحياة بعد الموت — كانوا يدفنون موتاهم مع أوانٍ للطعام والشراب.", unit:2},
  {k:["اقتصاد الرافدين","الحياة الاقتصادية في الرافدين"], a:"اعتمدت الحياة الاقتصادية في بلاد الرافدين على 3 أنشطة: الزراعة (أبرزها حدائق بابل المعلقة)، والصناعة (أسلحة وحلي وأدوات زراعة وفخار)، والتجارة.", unit:2},
  {k:["التجارة في الرافدين","التجارة في بلاد الرافدين"], a:"ازدهرت التجارة في بلاد الرافدين بسبب الموقع المتميز والأمن ووسائل النقل البرية والمائية.", unit:2},
  {k:["كتابة مسمارية","الواح طينية","كتبوا"], a:"الكتابة المسمارية نظام كتابة استخدمه سكان بلاد الرافدين على ألواح طينية، سُميت كذا لأنها تُكتب بأداة تشبه المسمار. السومريون أول من عرفها.", unit:2},
  {k:["فلك الرافدين","رياضيات الرافدين","الفلك في بلاد الرافدين","الحياة الفكرية في الرافدين","شهور السنة","تقسيم السنة","كم شهر السنة"], a:"تفوق أهل الرافدين بالرياضيات وأتقنوا العمليات الحسابية، وبالفلك رصدوا الكواكب وقسّموا السنة إلى 12 شهراً مع إضافة شهر كل 3 سنوات.", unit:2},
  {k:["حدائق بابل"], a:"حدائق بابل المعلقة من أبرز إنجازات الدولة البابلية بمجال الزراعة — حدائق مزروعة على شكل مدرّجات جبلية.", unit:2},
  {k:["بوابة عشتار"], a:"بوابة عشتار أضخم بوابات مدينة بابل، بناها نبوخذ نصر عام 575 ق.م، مزخرفة برسوم حيوانات، وموجودة حالياً بمتحف برلين.", unit:2},
  {k:["برج بابل"], a:"برج بابل بناء شُيّد على ارتفاع شاهق، ونُصبت فوقه المراصد الفلكية.", unit:2},
  {k:["ثور مجنح","الثور المجنح","سرجون الثاني"], a:"الثور المجنح من روائع النحت في بلاد الرافدين، نحته الملك الآشوري سرجون الثاني ليرمز للقوة والحكمة.", unit:2},
  {k:["مسلة","المسلات"], a:"المسلات ألواح حجرية نُحتت عليها أهم الأحداث الحربية وأخبار الانتصارات وسيرة الملوك — أشهرها مسلة حمورابي.", unit:2},

  // ===== الوحدة 3: السلطات الدستورية =====
  {k:["دستور","تعريف الدستور"], a:"الدستور هو مجموعة القواعد الأساسية اللي تحدد شكل الدولة، ونظام الحكم فيها، والسلطات العامة بها.", extra:"تشبيه يقرّبها: الدستور زي 'قوانين اللعبة' الأساسية بأي رياضة — كل اللاعبين (المواطنين والسلطات) يلتزمون فيها، وما تتغير بسهولة، عكس القرارات اليومية اللي ممكن تتبدل.", unit:3},
  {k:["اركان الدولة","أركان الدولة"], a:"للدولة 3 أركان رئيسة: السلطة، الشعب، والإقليم.", extra:"تشبيه: زي بيت له 3 أعمدة أساسية — لو انهار عمود واحد، ينهار البيت كامل. بدون شعب ما فيه دولة، بدون إقليم (أرض) ما فيه حدود، وبدون سلطة تحكم ما فيه نظام.", unit:3},
  {k:["مجلس الشورى","السلطة التشريعية","سلطة تشريعية","اعضاء مجلس الشورى","شروط عضو مجلس الشورى"], a:"مجلس الشورى يمثل السلطة التشريعية بدولة قطر (المادة 77)، عدد أعضائه لا يقل عن 45 عضواً بقرار أميري، مدته 4 سنوات، وشرط أعضائه الجنسية القطرية وأهل العلم والخبرة.", extra:"يشبه فكرة 'البرلمان' بدول ثانية — مجموعة أشخاص من أهل الخبرة يمثلون الرأي العام ويشاركون بصياغة القوانين ومراقبة أداء الحكومة، بدل ما يكون القرار كله بيد شخص واحد.", unit:3},
  {k:["اختصاصات مجلس الشورى","اقرار الموازنة العامة","الرقابة على السلطة التنفيذية"], a:"يختص مجلس الشورى (المادة 76) بـ: تشريع القوانين، إقرار الموازنة العامة للدولة، والرقابة على أعمال السلطة التنفيذية.", unit:3},
  {k:["سلطة تنفيذية","السلطة التنفيذية"], a:"السلطة التنفيذية (المادة 62) يتولاها الأمير يعاونه مجلس الوزراء، وتتكون من جزأين: أمير البلاد، ومجلس الوزراء.", unit:3},
  {k:["اختصاصات الامير","صلاحيات الأمير","امير البلاد","المصادقة على القوانين","يصادق على القوانين"], a:"يباشر الأمير (المادة 67): رسم السياسة العامة للدولة، المصادقة على القوانين (فلا يصبح القانون نافذاً إلا بعد مصادقة الأمير عليه)، واعتماد رؤساء البعثات الدبلوماسية والقنصلية.", unit:3},
  {k:["مجلس الوزراء","اختصاصات مجلس الوزراء","رئيس مجلس الوزراء"], a:"يتشكل مجلس الوزراء بأمر أميري بناء على اقتراح رئيس الوزراء، ويختص (المواد 120-121) بإدارة الشؤون الداخلية والخارجية، اقتراح وتنفيذ القوانين، والرقابة العليا على النظام الحكومي.", unit:3},
  {k:["سلطة قضائية","السلطة القضائية","استقلال القضاء","استقلال القضاة"], a:"السلطة القضائية ثالث السلطات الدستورية، وتُعدّ سلطة فاصلة بين بقية السلطات، وقوتها وسلامتها ضمان للحقوق والحريات. نصّت المادة (130) على أنها مستقلة ويتولاها القضاء بمختلف أنواعه ودرجاته، والمادة (131) على أن القضاة مستقلون لا سلطان عليهم في قضائهم لغير القانون.", unit:3},
  {k:["اختصاصات السلطة القضائية"], a:"تختص السلطة القضائية (المواد 138-140) بالفصل في المنازعات الإدارية، والفصل في المنازعات المتعلقة بدستورية القوانين واللوائح.", unit:3},
  {k:["المجلس الاعلى للقضاء","تعيين القضاة","يعين القضاة"], a:"المجلس الأعلى للقضاء تأسس عام 1999 لضمان استقلالية القضاء، ويختص بتعيين وترقية ونقل القضاة، والإشراف على المحاكم، وتطوير النظام القضائي.", unit:3},
  {k:["انواع المحاكم","أنواع المحاكم","درجات المحاكم","المحكمة الابتدائية","محكمة الاستئناف","محكمة التمييز"], a:"3 درجات للمحاكم بقطر: المحكمة الابتدائية (تنظر بالقضايا أول مرة)، محكمة الاستئناف (تنظر بالطعون على أحكام الابتدائية)، ثم محكمة التمييز (تنظر بالطعون بالتمييز).", unit:3},
  {k:["محكمة الاستثمار والتجارة"], a:"محكمة الاستثمار والتجارة محكمة متخصصة بدولة قطر تعتمد النظام الإلكتروني الكامل بجميع معاملاتها.", unit:3},
  {k:["مواد الدستور","المادة من الدستور","المادة"], a:"مواد الدستور القطري الواردة في الوحدة: المادة (60) الفصل بين السلطات مع تعاونها · (62) يتولى الأمير السلطة التنفيذية يعاونه مجلس الوزراء · (67) اختصاصات الأمير · (76) اختصاصات مجلس الشورى · (77) تكوين مجلس الشورى · (120، 121) اختصاصات مجلس الوزراء · (130) استقلال السلطة القضائية · (131) استقلال القضاة.", unit:3},
  {k:["السلطات الدستورية","السلطات الثلاث","توزيع السلطة في قطر"], a:"تتوزع السلطة في دولة قطر على ثلاث سلطات دستورية: السلطة التشريعية (مجلس الشورى)، والسلطة التنفيذية (الأمير يعاونه مجلس الوزراء)، والسلطة القضائية (القضاء المستقل).", unit:3},
  {k:["فصل السلطات","العلاقة بين السلطات"], a:"مبدأ الفصل بين السلطات (المادة 60) يعني فصل السلطات الثلاث مع تعاونها، هدفه منع الاستبداد بالسلطة ومنع فرض السياسات من جهة واحدة.", extra:"تشبيه بسيط: زي فريق كورة فيه مدرب (تنفيذية) ولاعبين (تشريعية تضع الخطة) وحكم مستقل (قضائية يفصل بالمخالفات) — لو صار المدرب هو نفسه الحكم، ما راح تكون المباراة عادلة.", unit:3},

  // ===== الوحدة 4: التوزيع الجغرافي للسكان =====
  {k:["تركز سكاني","تركز السكان في قطر"], a:"التركز السكاني هو وجود نسبة كبيرة من السكان بمناطق جغرافية معينة دون غيرها.", extra:"مثال من قطر: ساهمت شبكة المواصلات الحديثة في تركّز السكان على طول الساحل الشرقي وطرق المواصلات الرئيسة.", unit:4},
  {k:["تخلخل سكاني"], a:"التخلخل السكاني هو قلة أو ندرة وجود السكان بمناطق جغرافية معينة.", unit:4},
  {k:["سكان القارات","اكثر قارة سكانا","اقل قارة سكانا","ترتيب القارات حسب السكان"], a:"بحسب إحصاءات عام 2024: آسيا أكثر قارات العالم سكاناً (نحو 4770 مليون نسمة)، تليها إفريقيا (نحو 1487 مليون نسمة)، ثم أوروبا، ثم الأمريكتان، وأخيراً أوقيانوسيا الأقل سكاناً.", unit:4},
  {k:["عوامل طبيعية سكان","العوامل الطبيعية المؤثرة في توزيع السكان","العوامل الطبيعية"], a:"3 عوامل طبيعية تؤثر بتوزيع السكان: التضاريس (السهول الأفضل)، المناخ (الحرارة والأمطار)، والثروات المعدنية ومصادر الطاقة.", unit:4},
  {k:["سهول","تركز بشري","السهول الفيضية","حضارة النيل","تركز السكان قرب الانهار","السكان عند الانهار"], a:"السهول أفضل أنواع السطح للتركز السكاني: لسهولة مد الطرق والسكك الحديدية وإقامة المنشآت، ولخصوبة تربتها ووفرة المياه اللازمة للزراعة. ولذلك قامت الحضارات القديمة في السهول الفيضية، مثل حضارة النيل في مصر وحضارة دجلة والفرات في العراق.", unit:4},
  {k:["مناطق جبلية سكان","المناطق الجبلية","الجبال والسكان","مرتفعات اليمن","مرتفعات اثيوبيا"], a:"المناطق الجبلية غالباً طاردة للسكان بسبب وعورة تضاريسها وتعرّض تربتها للتعرية وصعوبة التنقل فيها، إلا أن بعضها يستقطب السكان لاعتدال مناخها وخصوبة تربتها، مثل مرتفعات اليمن ومرتفعات أثيوبيا.", unit:4},
  {k:["حرارة وتوزيع السكان","سيبيريا","المناطق الباردة والسكان","الاقاليم المعتدلة","الصحراء والسكان"], a:"الأقاليم شديدة الحرارة أو البرودة (كالصحاري وسيبيريا) أقل سكاناً، بينما الأقاليم المعتدلة (30-60°) تضم نصف سكان العالم.", unit:4},
  {k:["امطار وتوزيع السكان","الامطار والسكان","حوض الكونغو","حوض الامازون","جنوب شرق اسيا"], a:"كثافة السكان مرتبطة بالأمطار غالباً، لكن استثناء: حوض الكونغو والأمازون رغم غزارة أمطارهما كثافتهما منخفضة بسبب المستنقعات والحشرات الضارة.", unit:4},
  {k:["عوامل بشرية سكان","العوامل البشرية المؤثرة في توزيع السكان","العوامل البشرية"], a:"3 عوامل بشرية تؤثر بتوزيع السكان: الأنشطة الاقتصادية (خصوصاً الصناعة)، النقل والمواصلات، والحروب والمشكلات السياسية.", unit:4},
  {k:["انشطة اقتصادية سكان","الرعي","الزراعة وتوزيع السكان","الحرفة اللي ما تحتاج"], a:"الرعي لا يحتاج أعداداً كبيرة، الزراعة تحتاج أيدٍ عاملة كثيرة (تقل بالدول المتقدمة لاستخدام الآلات)، والصناعة تجذب تجمعات سكانية كبرى بالمدن.", unit:4},
  {k:["نقل ومواصلات سكان","النقل والمواصلات","السكك الحديدية"], a:"يترتب على تطور النقل والمواصلات: تعمير مناطق جديدة، وجذب السكان إلى المناطق النائية، والمساعدة على استغلال الموارد الاقتصادية. مثال: أدت السكك الحديدية إلى جذب السكان في غرب الولايات المتحدة الأمريكية.", extra:"ومن قطر: ساهمت شبكة المواصلات الحديثة في دولة قطر في تركز السكان على طول الساحل الشرقي وطرق المواصلات الرئيسة.", unit:4},
  {k:["هجرة قسرية","الحروب والسكان","الحروب والمشكلات السياسية","الفلسطينيين"], a:"الحروب والمشكلات السياسية تسبب هجرة قسرية للسكان نحو مناطق آمنة، مثال: نزوح الفلسطينيين للدول العربية المجاورة بعد الاحتلال الإسرائيلي 1948.", unit:4},
  {k:["الثروات المعدنية","مصادر الطاقة","راس تنورة","الاحمدي"], a:"يؤدي اكتشاف الثروات المعدنية ومصادر الطاقة إلى جذب السكان وقيام أنشطة تعدينية وصناعية؛ فاكتشاف النفط والغاز في منطقة الخليج العربي أدى إلى نشأة مدن مثل مسيعيد في دولة قطر، ورأس تنورة في السعودية، والأحمدي في الكويت.", unit:4},
  {k:["المدن الصناعية","الصناعة وتوزيع السكان"], a:"الصناعة تجذب تجمعات سكانية كبرى وتنشئ ما يُعرف بالمدن الصناعية، كما هو الحال في غرب أوروبا واليابان، ومدينتي مسيعيد ورأس لفان في دولة قطر.", unit:4},
  {k:["مسيعيد"], a:"مسيعيد مدينة صناعية بدولة قطر، نشأت بسبب اكتشاف النفط والغاز، وتجذب السكان لتوفر فرص العمل فيها.", unit:4},
  {k:["راس لفان","رأس لفان"], a:"رأس لفان مدينة صناعية أخرى بدولة قطر، مثل مسيعيد، جذبت السكان بسبب فرص العمل الصناعية.", unit:4},

  // ===== الوحدة 5: الخلافة العباسية =====
  {k:["نشاة الخلافة العباسية","نشأة الدولة العباسية","قيام الدولة العباسية","تاسيس الدولة العباسية","نسب العباسيين","العباس بن عبدالمطلب","عم الرسول"], a:"الدولة العباسية قامت بعد ثورة على الدولة الأموية انطلقت من إقليم خراسان، وانتصر العباسيون على الجيش الأموي في معركة الزاب الكبير في العراق سنة 132هـ، وتولى أبو العباس الخلافة ليكون أول الخلفاء العباسيين. ويرجع نسب العباسيين إلى العباس بن عبدالمطلب، عم النبي ﷺ.", unit:5},
  {k:["عصور الخلافة العباسية","عصور الدولة العباسية","العصر العباسي الاول"], a:"يُقسِّم المؤرخون الدولة العباسية إلى عصرين: العصر العباسي الأول (عصر القوة، 132–232هـ) تعاقب فيه تسعة خلفاء أقوياء، وتميّز فيه الحكم بالمركزية والعدل والمساواة، وازدهرت فيه الحضارة الإسلامية؛ ثم العصر العباسي الثاني (232–656هـ) الذي شهد مظاهر الضعف حتى السقوط.", unit:5},
  {k:["خلفاء العصر العباسي الاول","ترتيب الخلفاء العباسيين","الخلفاء التسعة","خلفاء الدولة العباسية","خليفة عباسي"], a:"الخلفاء التسعة بالترتيب: أبو العباس، أبو جعفر المنصور، المهدي، موسى الهادي، هارون الرشيد، الأمين، المأمون، المعتصم بالله، الواثق بالله. وأشهرهم هارون الرشيد، خامس الخلفاء العباسيين.", unit:5},
  {k:["ابو العباس","أبو العباس","اول خليفة عباسي","اول الخلفاء العباسيين"], a:"أبو العباس أول الخلفاء العباسيين (132–136هـ)، تولى الخلافة بعد انتصار العباسيين على الجيش الأموي في معركة الزاب الكبير سنة 132هـ.", unit:5},
  {k:["ابو جعفر المنصور","أبو جعفر المنصور","المنصور","بنى بغداد","بناء بغداد","مدينة بغداد","المؤسس الحقيقي للدولة العباسية"], a:"أبو جعفر المنصور ثاني الخلفاء العباسيين (136–158هـ)، ويُلقّب بـ«المؤسس الحقيقي» للدولة العباسية: ثبّت أركانها وقضى على الثورات الداخلية، وأنشأ جهازاً إدارياً محكماً للمراقبة والمحاسبة، وحصّن حدودها وخاصة الشمالية مع البيزنطيين، وبنى مدينة بغداد سنة 145هـ لتكون عاصمة للدولة. توفي وهو في طريقه لأداء فريضة الحج ودُفن في مكة المكرمة.", extra:"من أقواله المأثورة أن الحاكم يحتاج إلى أربعة أركان: قاضٍ عادل، وصاحب شرطة يحمي الضعيف من القوي، وصاحب خراج لا يظلم الرعية، وصاحب بريد يرفع له الأخبار بصدق.", unit:5},
  {k:["هارون الرشيد","الخليفة الخامس"], a:"هارون الرشيد خامس الخلفاء العباسيين وأشهرهم (170-193هـ)، عصره يُعتبر أزهى عصور الدولة، أنشأ مكتبة بيت الحكمة الشهيرة ببغداد، ونشطت الحياة الاقتصادية.", unit:5},
  {k:["مأمون","المأمون","الخليفة السابع"], a:"المأمون سابع الخلفاء العباسيين (198–218هـ)، ارتبط عصره بنهضة علمية وثقافية واسعة: بنى مراصد فلكية في دمشق وبغداد، ونشّط حركة الترجمة حتى كان يدفع للمترجم وزن الكتاب المترجم ذهباً، وأصبح بيت الحكمة في عهده أكبر مركز علمي وثقافي في العالم. وبعد وفاته خلفه أخوه المعتصم بالله.", extra:"كان محباً للعلم حتى قيل إنه «لو لم يكن خليفة لكان عالماً بارزاً».", unit:5},
  {k:["المهدي","الخليفة المهدي"], a:"المهدي ثالث خلفاء العصر العباسي الأول، حكم بين عامَي 158 و169هـ، بعد أبي جعفر المنصور.", unit:5},
  {k:["موسى الهادي","الهادي"], a:"موسى الهادي رابع خلفاء العصر العباسي الأول، حكم بين عامَي 169 و170هـ، وخلفه هارون الرشيد.", unit:5},
  {k:["الامين","الخليفة الامين"], a:"الأمين سادس خلفاء العصر العباسي الأول، حكم بين عامَي 193 و198هـ، بعد هارون الرشيد وقبل المأمون.", unit:5},
  {k:["المعتصم بالله","المعتصم"], a:"المعتصم بالله ثامن خلفاء العصر العباسي الأول (218–227هـ)، خلف أخاه المأمون، وعُرف بشجاعته وقوته، وفي عهده فُتحت مدينة عمورية سنة 223هـ.", unit:5},
  {k:["الواثق بالله","الواثق","العصر الذهبي للدولة العباسية"], a:"الواثق بالله تاسع خلفاء العصر العباسي الأول وآخرهم (227–232هـ)، وبوفاته سنة 232هـ انتهى ما يُعرف بـ«العصر الذهبي» للدولة العباسية.", unit:5},
  {k:["مراحل الدولة الاسلامية","العصر النبوي","الخلافة الراشدة","الدولة الاموية"], a:"مرّت الدولة الإسلامية بعدة مراحل تاريخية: العصر النبوي (1–11هـ)، فالخلافة الراشدة (11–40هـ)، فالدولة الأموية (40–132هـ)، ثم الدولة العباسية (132–656هـ).", unit:5},
  {k:["الفتوحات الاسلامية في العصر العباسي","الفتوحات العباسية"], a:"ساهمت الفتوحات الإسلامية في عهد الدولة العباسية بنشر رسالة الإسلام السمحة القائمة على حرية الإنسان واحترام الآخرين والعدل والمساواة شرقاً وغرباً، ومن أبرزها فتح مدينة عمورية سنة 223هـ في عهد الخليفة المعتصم بالله.", unit:5},
  {k:["بيت الحكمة"], a:"بيت الحكمة مكتبة ضخمة أنشأها هارون الرشيد ببغداد، ضمّت مؤلفات وكتب علمية نادرة، وأصبحت بعهد المأمون أكبر مركز علمي وثقافي بالعالم.", extra:"تقدر تتخيله زي 'جامعة بحثية كبرى' بمقاييس اليوم — فيه علماء ومترجمون وفلكيون يشتغلون ويطورون العلم، بس بدون إنترنت أو كهرباء، كل شي يدوياً ومكتوباً بخط اليد.", unit:5},
  {k:["فتح عمورية","عمورية","وامعتصماه"], a:"فُتحت مدينة عمورية سنة 223هـ في عهد الخليفة المعتصم بالله، وكانت من أقوى الحصون البيزنطية. يُروى أن امرأة مسلمة وقعت أسيرة عند الروم فصرخت «وامعتصماه»، فطالب المعتصم بإطلاق سراحها فرفض الإمبراطور البيزنطي، فقاد المعتصم الجيش بنفسه وفتح عمورية.", unit:5},
  {k:["العواصم والثغور","الحدود مع الروم"], a:"العواصم والثغور إقليم حصّنه العباسيون بالقلاع والحصون والأسوار على الحدود مع الروم (البيزنطيين) لحماية الدولة.", unit:5},
  {k:["ضعف الدولة العباسية","مظاهر ضعف الدولة العباسية","العصر العباسي الثاني","الاخطار الخارجية"], a:"شهدت الدولة العباسية في عصرها الثاني (232–656هـ) 3 مظاهر ضعف: التفكك والانقسام إلى دويلات مستقلة عن السلطة المركزية، وتردي الأوضاع الاقتصادية والاجتماعية (فساد وترف وزيادة النفقات وتراجع الموارد وانتشار الفوضى والثورات)، وتراجع النشاط العسكري ما أدى لتنامي الأخطار الخارجية: المغول من الشرق والصليبيون من الغرب.", unit:5},
  {k:["اسباب سقوط الدولة العباسية"], a:"5 أسباب لسقوط الدولة العباسية: ضعف الخلفاء وعدم قدرتهم على إدارة شؤون الدولة، سيطرة عناصر غير متخصصة على النظام الإداري والعسكري، اتساع رقعة الدولة ما أدى لظهور دويلات مستقلة، إهمال الزراعة والصناعة والتجارة، وتنامي الأطماع الخارجية وأخطرها الغزو الصليبي والغزو المغولي.", unit:5},
  {k:["سقوط الدولة العباسية","المغول","اسقط الدولة العباسية"], a:"سقطت الدولة العباسية عام 656هـ لما دخل المغول بغداد، بعد عصر طويل من الضعف والتفكك والانقسام لدويلات مستقلة.", extra:"الدرس المستفاد من سقوطها: الدول القوية ما تسقط فجأة عادة، هي تضعف تدريجياً من الداخل (فساد، انقسام، إهمال الاقتصاد) قبل ما يستغل عدو خارجي هذا الضعف — نفس الفكرة تنطبق على أي مؤسسة أو مجتمع اليوم.", unit:5},

  // ===== الوحدة 6: الأمن الوطني =====
  {k:["امن وطني","الأمن الوطني","تعريف الامن الوطني"], a:"الأمن الوطني هو قدرة الدولة على حماية أراضيها وشعبها من أي عدوان خارجي، والتصدي للمشاكل الداخلية، وترسيخ الولاء والانتماء للوطن والقيادة.", unit:6},
  {k:["ابعاد الامن","أبعاد الأمن الوطني"], a:"4 أبعاد للأمن الوطني: العسكري، السياسي، الاقتصادي، والاجتماعي (وضمنه الأمن السيبراني).", unit:6},
  {k:["امن عسكري","الأمن العسكري"], a:"الأمن العسكري يهدف إلى تعزيز القدرة الدفاعية للدولة في مواجهة التهديدات الخارجية، وإخضاع جميع الأفراد والجماعات لسلطة القانون، بما يسهم في جعلهم مواطنين صالحين.", unit:6},
  {k:["امن سياسي","الأمن السياسي","الالتفاف حول القيادة"], a:"الأمن السياسي يُكمّل الجانب العسكري، ويهدف إلى حماية البلاد من العوامل المسبّبة للفوضى داخلياً وخارجياً، ويشمل الالتفاف حول القيادة.", extra:"مثال من الكتاب: الاستقبال الشعبي الحاشد لسمو الأمير تميم بن حمد آل ثاني عند عودته من الأمم المتحدة في 24 سبتمبر 2017، حيث حمل المواطنون صوره وأعلام الدولة تعبيراً عن الولاء.", unit:6},
  {k:["امن اقتصادي","الأمن الاقتصادي"], a:"الأمن الاقتصادي يهدف لتحقيق الاستغلال الأمثل للموارد، زيادة الاكتفاء الذاتي، وإيجاد أسواق متعددة خارجياً.", extra:"والهدف من إيجاد أسواق خارجية متعددة: تجنّب تحكّم أي جهة خارجية بالقرار الاقتصادي للدولة.", unit:6},
  {k:["امن اجتماعي","الأمن الاجتماعي","الهوية الوطنية"], a:"الأمن الاجتماعي يهدف إلى الحفاظ على أمن المجتمع وتماسكه واستقراره، بما يحقق النمو والتنمية والرفاهية، دون المساس بالثوابت كالدين واللغة والهوية الوطنية والقيم الأخلاقية. ويندرج ضمنه الأمن السيبراني.", unit:6},
  {k:["امن سيبراني","الأمن السيبراني","الاستراتيجية الوطنية للامن السيبراني"], a:"الأمن السيبراني يندرج ضمن الأمن الاجتماعي، نظراً للاعتماد المتزايد على تقنية المعلومات والإنترنت، وقد وضعت دولة قطر «الاستراتيجية الوطنية للأمن السيبراني» لمواجهة هذه التحديات.", extra:"مثال يخصّك أنت شخصياً: لما تحط كلمة مرور قوية لحسابك، أو ما تضغط رابط مشبوه يوصلك برسالة، أنت فعلياً تمارس 'أمن سيبراني' على مستوى صغير — نفس المبدأ تطبقه الدولة بمستوى أكبر بكثير لحماية بياناتها وأنظمتها الحساسة.", unit:6},
  {k:["مقومات الامن","مقومات الامن الوطني"], a:"4 مقومات للأمن الوطني: استقرار النظام السياسي، ترسيخ الديمقراطية وتكافؤ الفرص، التوافق مع الأمن العالمي، وتطوير أجهزة الأمن.", extra:"تخيلها زي مقومات صحة جسم الإنسان: نظام غذائي مستقر (استقرار سياسي)، عدالة بتوزيع الفرص بين أعضاء الجسم (تكافؤ الفرص)، توافق مع البيئة المحيطة (التوافق العالمي)، وجهاز مناعة قوي يتطور (أجهزة الأمن) — لو اختل أحدها يضعف الجسم كامل.", unit:6},
  {k:["الاستقرار السياسي في قطر","حكم ال ثاني"], a:"تتمتع دولة قطر باستقرار سياسي في ظل حكم أسرة آل ثاني، وقد حظيت بمكانة إقليمية ودولية مرموقة في عهد حضرة صاحب السمو الشيخ تميم بن حمد آل ثاني، الذي يُعدّ رمزاً للقيادة الحكيمة التي تجاوزت بالدولة الأزمات وعزّزت روح التلاحم القطري.", unit:6},
  {k:["مؤسسات الامن الوطني","المؤسسات الوطنية والامن"], a:"من المؤسسات الوطنية التي تحقق الأمن الوطني: وزارة الدفاع (تأمين الحدود وتنظيم الخدمة الوطنية العسكرية)، ووزارة الداخلية بإداراتها العامة: شرطة النجدة (الفزعة)، والمرور، والدفاع المدني، ومكافحة المخدرات، وأمن السواحل والحدود.", unit:6},
  {k:["وزارة الدفاع","القوات المسلحة القطرية","افرع القوات المسلحة","الخدمة الوطنية"], a:"وزارة الدفاع القطرية تتولى مهام أبرزها تأمين حدود دولة قطر وتنظيم الخدمة الوطنية العسكرية. وتتكون القوات المسلحة القطرية من ثلاثة أفرع: القوات الأميرية البرية القطرية، والقوات الأميرية البحرية القطرية، وقوات الدفاع الجوي الأميري القطري.", unit:6},
  {k:["وزارة الداخلية"], a:"وزارة الداخلية القطرية تضم عدة إدارات: النجدة (الفزعة)، المرور، الدفاع المدني، مكافحة المخدرات، وأمن السواحل والحدود.", unit:6},
  {k:["فزعة","الفزعة","النجدة","الشرطة"], a:"شرطة النجدة (الفزعة) إدارة تابعة لوزارة الداخلية، مهمتها الاستجابة السريعة لحفظ أمن المجتمع.", unit:6},
  {k:["ادارة المرور"], a:"الإدارة العامة للمرور تسعى لوضع الخطط والضوابط للحركة المرورية، وتحقيق السلامة على الطريق.", unit:6},
  {k:["دفاع مدني","الدفاع المدني"], a:"الإدارة العامة للدفاع المدني تواجه الحوادث والكوارث وحالات الطوارئ لحماية الأرواح والممتلكات.", unit:6},
  {k:["مكافحة المخدرات"], a:"الإدارة العامة لمكافحة المخدرات تعمل على مكافحة وضبط جرائم المخدرات بشتى صورها.", unit:6},
  {k:["امن السواحل والحدود","السواحل"], a:"الإدارة العامة لأمن السواحل والحدود تراقب وتحمي حدود وسواحل الدولة.", unit:6},
  {k:["دور المواطن في الامن الوطني","واجبات المواطن","واجب المواطن نحو الامن","احافظ على الامن الوطني","الشائعات","عدم تداول الشائعات"], a:"دور المواطن الصالح: الالتفاف حول القيادة، تقديم المصلحة العامة على الخاصة، الخدمة الوطنية، نبذ التعصب القبلي، دعم الاقتصاد الوطني، وعدم تداول الشائعات.", unit:6},

  // ===== أسئلة عن الموقع نفسه =====
  {k:["نظام النقاط","كيف اجمع نقاط"], a:"النقاط تُكسب بالإجابة الصحيحة في ألعاب المراجعة وتُحفظ بحساب الطالب — ودخول الطلاب بحساباتهم متوقف حالياً بقرار المعلم. تقدر تتصفح المنهج وتسألني عن أي مفهوم بدون حساب."},
  {k:["كيف اسجل","تسجيل دخول"], a:"دخول الطلاب متوقف حالياً بقرار المعلم — ما تحتاج حساباً: تصفّح «المنهج» واسألني عن أي مفهوم مباشرة."},
];
